<style lang="scss" scoped src="./reconciliation-summary-block.scss"></style>

<script>
import { Vue, Prop, Component } from "vue-property-decorator";
import { CurrencyNotation, CurrencyNotationValues } from "../constants";
import { has } from "../../util/has";
import { format } from "date-fns";
import {
  TransactionMode,
  TransactionModeValues,
} from "./reconciliatoin-summary-block.contants";

@Component
export default class ReconciliationSummaryBlock extends Vue {
  @Prop({
    type: Number,
    default: 0,
  })
  amount;

  @Prop({
    type: String,
    default: "",
  })
  type;

  @Prop({
    type: String,
    default: "",
  })
  status;

  @Prop({
    type: Date,
    default: new Date(),
  })
  date;

  @Prop({
    type: String,
    default: "",
  })
  transaction_Id;

  @Prop({
    type: String,
    default: CurrencyNotation.USD,
    validator: has(CurrencyNotationValues),
  })
  currency;

  @Prop({
    type: String,
    default: TransactionMode.INFO,
    validator: has(TransactionModeValues),
  })
  mode;

  CurrencyNotation = CurrencyNotation;

  get dateStr() {
    return format(this.date, "MM/dd/yyyy");
  }

  get modeClass() {
    return this.mode;
  }

  handleView() {
    /**
     * This event emits when the user clicks to view this component
     */
    this.$emit("view");
  }
}
</script>

<template>
  <div class="ReconciliationSummaryBlock">
    <div class="ReconciliationSummaryBlock__Left">
      <div class="ReconciliationSummaryBlock__Amount">
        <div class="ReconciliationSummaryBlock__Dollar">
          {{ currency }}
        </div>
        <div class="ReconciliationSummaryBlock__Number">
          {{ amount }}
        </div>
      </div>
      <div class="ReconciliationSummaryBlock__Type">
        {{ type.toUpperCase() }}
      </div>
    </div>
    <div class="ReconciliationSummaryBlock__Right">
      <div :class="['ReconciliationSummaryBlock__RightContent', modeClass]">
        <div class="ReconciliationSummaryBlock__Info">
          <div class="ReconciliationSummaryBlock__Status">
            {{ status.toUpperCase() }}
          </div>
          <div class="ReconciliationSummaryBlock__Id">
            {{ `${dateStr} — ID ${transaction_Id}` }}
          </div>
        </div>
        <div class="ReconciliationSummaryBlock__Button" @click="handleView">
          {{ "View Transaction" }}
        </div>
      </div>
    </div>
  </div>
</template>
